/**
 * node_modules의 Leaflet + MarkerCluster를 읽어
 * src/assets/leafletBundle.ts 로 인라인 번들 생성
 * 실행: node scripts/bundle-leaflet.js
 */
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const nm = path.join(root, '../../node_modules');

function read(p) {
  return fs.readFileSync(p, 'utf8').replace(/`/g, '\\`').replace(/\${/g, '\\${');
}

const leafletJs  = read(path.join(nm, 'leaflet/dist/leaflet.js'));
const leafletCss = read(path.join(nm, 'leaflet/dist/leaflet.css'));
const clusterJs  = read(path.join(nm, 'leaflet.markercluster/dist/leaflet.markercluster.js'));
const clusterCss = read(path.join(nm, 'leaflet.markercluster/dist/MarkerCluster.css'));
const clusterDefaultCss = read(path.join(nm, 'leaflet.markercluster/dist/MarkerCluster.Default.css'));

const output = `// Auto-generated by scripts/bundle-leaflet.js — do not edit manually
export const LEAFLET_JS = \`${leafletJs}\`;
export const LEAFLET_CSS = \`${leafletCss}\`;
export const CLUSTER_JS = \`${clusterJs}\`;
export const CLUSTER_CSS = \`${clusterCss}\n${clusterDefaultCss}\`;
`;

const outPath = path.join(root, 'src/assets/leafletBundle.ts');
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, output);

const kb = Math.round(fs.statSync(outPath).size / 1024);
console.log(`✅ leafletBundle.ts 생성 완료 (${kb} KB)`);
